contracts/samples/PGAPaymaster.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.12;

/* solhint-disable reason-string */

import "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";


import "../core/BasePaymaster.sol";
import "./IAssetOracle.sol";
import {Exec} from "../utils/Exec.sol";
import "hardhat/console.sol";

/**
 * A sample paymaster that defines itself as a token to pay for gas.
 * The paymaster IS the token to use, since a paymaster cannot use an external contract.
 * Also, the exchange rate has to be fixed, since it can't reference an external Uniswap or other exchange contract.
 * subclass should override "getTokenValueOfEth" to provide actual token exchange rate, settable by the owner.
 * Known Limitation: this paymaster is exploitable when put into a batch with multiple ops (of different accounts):
 * - while a single op can't exploit the paymaster (if postOp fails to withdraw the tokens, the user's op is reverted,
 *   and then we know we can withdraw the tokens), multiple ops with different senders (all using this paymaster)
 *   in a batch can withdraw funds from 2nd and further ops, forcing the paymaster itself to pay (from its deposit)
 * - Possible workarounds are either use a more complex paymaster scheme (e.g. the DepositPaymaster) or
 *   to whitelist the account and the called method ids.
 */
contract PGAPaymaster is BasePaymaster {

    using UserOperationLib for UserOperation;
    using SafeERC20 for IERC20;

    uint256 constant PAYMASTER_TOKEN_ADDRESS_OFFSET = 20; // 20 bytes for token address
    uint256 constant PAYMASTER_PERMIT_OWNER_OFFSET = PAYMASTER_TOKEN_ADDRESS_OFFSET + 20;
    uint256 constant PAYMASTER_PERMIT_SIGNATURE_OFFSET = PAYMASTER_PERMIT_OWNER_OFFSET + 20;
    //calculated cost of the postOp
    uint256 constant public COST_OF_POST = 35000;
    uint256 constant public MAX_ETH_PER_TOKEN_RATE = 10000;
    IAssetOracle public assetOracle;
    address public pgaToken;
    address public theFactory;
    uint256 public ethPerTokenRate;

    event UserOperationRevertReason(bytes revertReason);
    event SetEthPerTokenRate(uint256 ethPerTokenRate);

    error PermitFailed(string reason);
    error AllowanceFailed(uint256 amount, string reason);

    constructor(
        IEntryPoint entryPoint,
        address _pgaToken,
        address accountFactory,
        IAssetOracle _assetOracle
    ) BasePaymaster(entryPoint) {
        require(_pgaToken != address(0), "Invalid token");
        require(accountFactory != address(0), "Invalid account factory");
        require(address(_assetOracle) != address(0), "Invalid asset oracle");
        require(address(entryPoint) != address(0), "Invalid entrypoint oracle");
        ethPerTokenRate = MAX_ETH_PER_TOKEN_RATE;
        assetOracle = _assetOracle;
        theFactory = accountFactory;
        pgaToken = _pgaToken;
    }

    /**
     * translate the given eth value to token amount
     * @param ethBought the required eth value we want to "buy"
     * @return requiredTokens the amount of tokens required to get this amount of eth
     */
    function getTokenValueOfEth(uint256 ethBought) internal view virtual returns (uint256 requiredTokens) {
        requiredTokens = ethBought * ethPerTokenRate / MAX_ETH_PER_TOKEN_RATE;
    }

    function setEthPerTokenRate(uint256 _ethPerTokenRate) external onlyOwner {
        require(_ethPerTokenRate > 0 && _ethPerTokenRate < MAX_ETH_PER_TOKEN_RATE);
        ethPerTokenRate = _ethPerTokenRate;
        emit SetEthPerTokenRate(_ethPerTokenRate);
    }

    /**
      * validate the request:
      * if this is a constructor call, make sure it is a known account.
      * verify the sender has enough tokens.
      * (since the paymaster is also the token, there is no notion of "approval")
      */
    function _validatePaymasterUserOp(UserOperation calldata userOp, bytes32 /*userOpHash*/, uint256 requiredPreFund)
    internal override returns (bytes memory context, uint256 validationData) {
        uint256 tokenPrefund = getTokenValueOfEth(requiredPreFund);

        // verificationGasLimit is dual-purposed, as gas limit for postOp. make sure it is high enough
        // make sure that verificationGasLimit is high enough to handle postOp
        require(userOp.verificationGasLimit > COST_OF_POST, "PGAPaymaster: gas too low for postOp");

        if (userOp.initCode.length != 0) {
            _validateConstructor(userOp);
            require(IERC20(pgaToken).balanceOf(userOp.sender) >= tokenPrefund, "PGAPaymaster: no balance (pre-create)");
        } else {
            require(IERC20(pgaToken).balanceOf(userOp.sender) >= tokenPrefund, "PGAPaymaster: no balance");
        }
        require(userOp.paymasterAndData.length > 20, "PGAPaymaster: no signature");

        if (userOp.paymasterAndData.length < PAYMASTER_PERMIT_SIGNATURE_OFFSET + 65) {//20 bytes token address + 65 bytes permit signature
            revert("Incorrect paymasterAndData length");
        }

        address tokenAddress = address(bytes20(userOp.paymasterAndData[PAYMASTER_TOKEN_ADDRESS_OFFSET:PAYMASTER_PERMIT_OWNER_OFFSET]));
        address signer = address(bytes20(userOp.paymasterAndData[PAYMASTER_PERMIT_OWNER_OFFSET:PAYMASTER_PERMIT_SIGNATURE_OFFSET]));
        bytes memory permitSignature = userOp.paymasterAndData[PAYMASTER_PERMIT_SIGNATURE_OFFSET:];

        if (tokenAddress != pgaToken) {
            revert ("unmatched token");
        }
        verifySignature(signer, userOp.sender, 5*17, permitSignature);

        return (abi.encode(userOp.sender, signer), 0);
    }

    function uint2str(uint _i) internal pure returns (string memory) {
        if (_i == 0) {
            return "0";
        }
        uint j = _i;
        uint length;
        while (j != 0) {
            length++;
            j /= 10;
        }
        bytes memory bstr = new bytes(length);
        uint k = length;
        while (_i != 0) {
            k = k-1;
            uint8 temp = (48 + uint8(_i - _i / 10 * 10));
            bytes1 b1 = bytes1(temp);
            bstr[k] = b1;
            _i /= 10;
        }
        return string(bstr);
    }

    function splitSignature(bytes memory signature) public pure returns(uint8, bytes32, bytes32) {
        uint8 v;
        bytes32 r;
        bytes32 s;
        // Extract r, s, v from signature
        assembly {
        // First 32 bytes after the length prefix
            r := mload(add(signature, 32))
        // Next 32 bytes
            s := mload(add(signature, 64))
        // Final byte (first byte of the next 32 bytes)
            v := byte(0, mload(add(signature, 96)))
        }
        // Adjust v value (27 or 28)
        if (v < 27) {
            v += 27;
        }
        require(v == 27 || v == 28, "Invalid signature v value");
        return (v, r, s);
    }

    function verifySignature(address signer, address spender, uint256 value, bytes memory signature) public  {
        require(signature.length == 65, "Invalid signature length");
        (uint8 v, bytes32 r, bytes32 s) = splitSignature(signature);

        IERC20Permit permitToken = IERC20Permit(pgaToken);
        try permitToken.permit(signer, spender, value, type(uint256).max, v, r, s) {
            // continue as normal
        } catch (bytes memory reason) {
            // Because the permitSignature enters a mempool, it may be frontrun.
            // Instead, we allow failed permits to continue expecting the permit was already run.
            if (reason.length > 0) {
                // If there's a reason string, decode it
                string memory revertReason = abi.decode(reason, (string));
                revert PermitFailed(revertReason);
            } else {
                revert PermitFailed("Permit failed without reason");
            }
        }
    }
    /**
 * @notice A helper function for parsing permit data from paymasterAndData.
     */
    function parsePermitData(bytes calldata paymasterAndData)
    public
    pure
    returns (address tokenAddress, address signer, bytes calldata permitSignature)
    {
        return (
            address(bytes20(paymasterAndData[PAYMASTER_TOKEN_ADDRESS_OFFSET:PAYMASTER_PERMIT_OWNER_OFFSET])),
            address(bytes20(paymasterAndData[PAYMASTER_PERMIT_OWNER_OFFSET:PAYMASTER_PERMIT_SIGNATURE_OFFSET])),
            paymasterAndData[PAYMASTER_PERMIT_SIGNATURE_OFFSET:]
        );
    }

    // when constructing an account, validate constructor code and parameters
    // we trust our factory (and that it doesn't have any other public methods)
    function _validateConstructor(UserOperation calldata userOp) internal virtual view {
        address factory = address(bytes20(userOp.initCode[0 : 20]));
        require(factory == theFactory, "PGAPaymaster: wrong account factory");
    }



    /**
     * actual charge of user.
     * this method will be called just after the user's TX with mode==OpSucceeded|OpReverted (account pays in both cases)
     * BUT: if the user changed its balance in a way that will cause  postOp to revert, then it gets called again, after reverting
     * the user's TX , back to the state it was before the transaction started (before the validatePaymasterUserOp),
     * and the transaction should succeed there.
     */
    function _postOp(PostOpMode mode, bytes calldata context, uint256 actualGasCost) internal override {
        //we don't really care about the mode, we just pay the gas with the user's tokens.
        (mode);
        (address sender, address signer) = abi.decode(context, (address, address));
        uint256 charge = getTokenValueOfEth(actualGasCost);
//        actualGasCost is known to be no larger than the above requiredPreFund, so the transfer should succeed.
        uint256 allowance = IERC20(pgaToken).allowance(signer, sender);
        if (allowance < charge) {
            revert AllowanceFailed(allowance, "No enough allowance");
        }
        SafeERC20.safeTransferFrom(IERC20(pgaToken), signer, address(this), charge);
    }
}

